const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');const mini=document.querySelector('#miniMap').getContext('2d'),full=document.querySelector('#fullMap').getContext('2d');
const W=2600,H=2000,game=document.querySelector('#game');let cw=innerWidth,ch=innerHeight,dpr=1;function resize(){cw=innerWidth;ch=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),rnd=(n)=>Math.floor(Math.random()*n);
let state='lobby',mode='SOLO',control='auto',soundOn=true,player=null,bots=[],bullets=[],loot=[],decor=[],buildings=[],trees=[],keys={},camera={x:0,y:0},safe={x:1300,y:1000,r:930,target:930},mapOpen=false,gameTime=0,last=0,zoneStart=80,kills=0,dropTime=0,shootHeld=false,aiming=false,crouched=false,moveTouch={x:0,y:0},joyId=null,weaponIndex=0,toastTimer=0,fireCooldown=0,spawned=0,gamepadType='';
const weapons=[{name:'M4A1',mag:30,reserve:120,damage:24,rate:.16,speed:900,color:'#d4b86a'},{name:'MP40',mag:32,reserve:160,damage:17,rate:.095,speed:800,color:'#e9a458'},{name:'SCAR',mag:24,reserve:96,damage:29,rate:.21,speed:980,color:'#9dc9aa'}];
const places=[['FAVELA',900,720],['FÁBRICA',1750,620],['VILA DO FAROL',1960,1350],['MATA ALTA',650,1430],['PRAIA DO SUL',1290,1760],['PONTE VELHA',1340,1030],['TORRE DE RÁDIO',2010,940]];
function makeMap(){buildings=[];trees=[];decor=[];loot=[];
// Island and winding roads are rendered in world-space; districts get distinct structures.
for(let i=0;i<115;i++){let x=rand(110,W-110),y=rand(110,H-110);if((x<570||x>2070)&&(y<500||y>1570))continue;trees.push({x,y,r:rand(14,32),tone:rnd(4),p:rand(0,7)})}
// Favela clusters, compact colorful houses
for(let row=0;row<5;row++)for(let col=0;col<7;col++){let x=660+col*87+rand(-9,9),y=490+row*82+rand(-9,9);if(Math.hypot(x-920,y-690)<300)buildings.push({x,y,w:rand(54,73),h:rand(46,66),type:'home',tone:rnd(5),roof:rnd(3)})}
// Factory warehouse and surrounding sheds
for(let i=0;i<10;i++){let x=1580+(i%4)*120+rand(-12,10),y=430+Math.floor(i/4)*112+rand(-12,10);buildings.push({x,y,w:i%4===0?105:rand(58,85),h:i%4===0?75:rand(50,72),type:'factory',tone:rnd(3),roof:rnd(3)})}
// coastal village
for(let i=0;i<18;i++){let x=1750+(i%6)*75+rand(-15,15),y=1210+Math.floor(i/6)*92+rand(-13,13);buildings.push({x,y,w:rand(45,69),h:rand(43,60),type:'home',tone:rnd(5),roof:rnd(3)})}
// scattered landmarks and outposts
[[1340,1000,190,75,'bridge'],[2020,880,98,220,'tower'],[1230,1190,100,75,'home'],[440,1050,100,70,'home'],[1460,1510,110,80,'home'],[1060,380,95,70,'home']].forEach(([x,y,w,h,type])=>buildings.push({x,y,w,h,type,tone:rnd(5),roof:rnd(3)}));
for(let i=0;i<105;i++){let x=rand(180,W-180),y=rand(180,H-180);if(buildings.some(b=>Math.abs(x-b.x)<b.w&&Math.abs(y-b.y)<b.h))continue;loot.push({x,y,type:['ammo','med','armor','grenade','weapon'][rnd(5)],taken:false})}}
makeMap();
function startGame(){state='drop';game.classList.add('game-active');document.querySelector('#lobby').classList.remove('active');document.querySelector('#gameUi').classList.add('active');document.querySelector('#settings').classList.remove('show');document.querySelector('#result').classList.remove('show');gameTime=0;kills=0;spawned=0;dropTime=0;safe={x:rand(980,1600),y:rand(730,1270),r:930,target:930};player={x:rand(900,1500),y:rand(760,1250),angle:-Math.PI/2,hp:100,armor:50,ammo:30,reserve:120,weapon:0,alive:true,speed:225,heal:2,grenades:1,inv:1.6,parachute:true};bots=[];bullets=[];for(let i=0;i<49;i++){let a=rand(0,Math.PI*2),r=rand(240,1100);bots.push({x:clamp(player.x+Math.cos(a)*r,120,W-120),y:clamp(player.y+Math.sin(a)*r,120,H-120),angle:rand(0,6.28),hp:100,armor:rand(0,55),alive:true,speed:rand(95,150),think:rand(0,2),shoot:rand(.2,2),name:['Sombra','Mandrake','Lua','Falcão','Caveira','Nina','Trovão','Pardal'][rnd(8)],team:Math.floor(i/(mode==='SQUAD'?4:mode==='DUO'?2:1)),weapon:rnd(3),crouch:false});}weaponIndex=0;document.querySelector('#ammo').textContent=30;document.querySelector('#reserve').textContent=120;document.querySelector('#weaponName').textContent='M4A1';showToast('SALTE! ESCOLHA SUA ROTA');last=performance.now();requestAnimationFrame(loop)}
function showToast(t){let el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');toastTimer=2.1}
function endGame(win,by=''){state='result';game.classList.remove('game-active');document.querySelector('#resultTitle').textContent=win?'BOOYAH!':'ELIMINADO';document.querySelector('#resultTitle').style.color=win?'var(--lime)':'#ff795e';document.querySelector('#resultEyebrow').textContent=win?'VITÓRIA ROYALE · SOBREVIVENTE':'VOCÊ FOI ELIMINADO';document.querySelector('#resultCopy').textContent=win?'A ilha tem um novo campeão. Uma queda perfeita.':'Eliminado por '+(by||'um combatente')+'. Reúna seu esquadrão e tente novamente.';document.querySelector('#resultKills').textContent=kills;document.querySelector('#resultTime').textContent=timeFmt(gameTime);document.querySelector('#result').classList.add('show')}
function timeFmt(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0')}
function nearestLoot(){if(!player)return null;return loot.filter(l=>!l.taken&&dist(l,player)<55).sort((a,b)=>dist(a,player)-dist(b,player))[0]}
function pickup(){let l=nearestLoot();if(!l){showToast('NENHUM ITEM POR PERTO');return}l.taken=true;switch(l.type){case'ammo':player.reserve+=36;showToast('+36 MUNIÇÃO');break;case'med':player.heal=Math.min(4,player.heal+1);showToast('KIT MÉDICO PEGADO');break;case'armor':player.armor=Math.min(100,player.armor+30);showToast('COLETE +30');break;case'grenade':player.grenades++;showToast('GRANADA PEGADA');break;case'weapon':player.weapon=(player.weapon+1)%3;player.ammo=weapons[player.weapon].mag;player.reserve+=48;showToast(weapons[player.weapon].name+' EQUIPADA');break}syncHud()}
function heal(){if(player&&player.heal>0&&player.hp<100){player.heal--;player.hp=Math.min(100,player.hp+45);showToast('KIT DE CURA · +45 VIDA');syncHud()}else showToast('SEM KIT OU VIDA COMPLETA')}
function reload(){if(!player)return;let w=weapons[player.weapon],n=Math.min(w.mag-player.ammo,player.reserve);if(n>0){player.ammo+=n;player.reserve-=n;syncHud();showToast('RECARREGADO')}else showToast('SEM MUNIÇÃO')}
function syncHud(){if(!player)return;document.querySelector('#healthFill').style.width=player.hp+'%';document.querySelector('#healthText').textContent=Math.ceil(player.hp);document.querySelector('#armorFill').style.width=player.armor+'%';document.querySelector('#armorText').textContent=Math.ceil(player.armor);document.querySelector('#ammo').textContent=player.ammo;document.querySelector('#reserve').textContent=player.reserve;document.querySelector('#weaponName').textContent=weapons[player.weapon].name;document.querySelector('#kills').textContent=kills;document.querySelector('#alive').textContent=Math.max(1,bots.filter(b=>b.alive).length+1)}

