function syncHud(){if(!player)return;document.querySelector('#healthFill').style.width=player.hp+'%';document.querySelector('#healthText').textContent=Math.ceil(player.hp);document.querySelector('#armorFill').style.width=player.armor+'%';document.querySelector('#armorText').textContent=Math.ceil(player.armor);document.querySelector('#ammo').textContent=player.ammo;document.querySelector('#reserve').textContent=player.reserve;document.querySelector('#weaponName').textContent=weapons[player.weapon].name;document.querySelector('#kills').textContent=kills;document.querySelector('#alive').textContent=Math.max(1,bots.filter(b=>b.alive).length+1)}
function drawGround(g){g.fillStyle='#26705a';g.fillRect(0,0,W,H);g.save();g.beginPath();g.moveTo(0,0);g.lineTo(W,0);g.lineTo(W,H);g.lineTo(0,H);g.closePath();g.clip();
// textured island turf, coastal sand and sea edge
for(let y=0;y<H;y+=80){for(let x=0;x<W;x+=80){g.fillStyle=((x/80+y/80)%2<1)?'#34785d':'#327359';g.globalAlpha=.16;g.fillRect(x,y,80,80)}}g.globalAlpha=1;
g.fillStyle='#d5bc83';g.beginPath();g.ellipse(W/2,H/2,1250,940,0,0,Math.PI*2);g.fill();g.fillStyle='#31765b';g.beginPath();g.ellipse(W/2,H/2,1190,885,0,0,Math.PI*2);g.fill();
// pale beach edging
 g.strokeStyle='#ead59b';g.lineWidth=28;g.beginPath();g.ellipse(W/2,H/2,1200,895,0,0,Math.PI*2);g.stroke();
// wooded zones tint
 g.fillStyle='#225d4b';g.globalAlpha=.28;g.beginPath();g.ellipse(520,1370,390,430,-.35,0,Math.PI*2);g.fill();g.beginPath();g.ellipse(2130,490,320,260,.2,0,Math.PI*2);g.fill();g.globalAlpha=1;
// road network, layered curves
 g.lineCap='round';g.lineJoin='round';g.strokeStyle='#9e966f';g.lineWidth=46;g.beginPath();g.moveTo(260,1050);g.bezierCurveTo(600,930,620,1130,980,1020);g.bezierCurveTo(1270,900,1440,820,1710,900);g.bezierCurveTo(1950,980,2150,1020,2340,900);g.stroke();g.beginPath();g.moveTo(980,1020);g.bezierCurveTo(1040,750,1210,630,1390,490);g.bezierCurveTo(1580,370,1670,370,1840,260);g.stroke();g.beginPath();g.moveTo(980,1020);g.bezierCurveTo(1020,1280,1170,1450,1310,1660);g.stroke();g.strokeStyle='#c2b387';g.lineWidth=3;g.setLineDash([12,13]);g.beginPath();g.moveTo(260,1050);g.bezierCurveTo(600,930,620,1130,980,1020);g.bezierCurveTo(1270,900,1440,820,1710,900);g.bezierCurveTo(1950,980,2150,1020,2340,900);g.stroke();g.setLineDash([]);
// factory yard and favela open lanes
 g.fillStyle='#64785e';g.globalAlpha=.26;g.fillRect(1500,350,490,390);g.globalAlpha=1;
 g.restore();
}
function drawBuilding(g,b){g.save();g.translate(b.x,b.y);g.fillStyle='#0005';g.fillRect(-b.w/2+7,-b.h/2+9,b.w,b.h);if(b.type==='bridge'){g.fillStyle='#5e6057';g.fillRect(-b.w/2,-b.h/2,b.w,b.h);g.fillStyle='#c2b88e';g.fillRect(-b.w/2+10,-b.h/2+12,b.w-20,b.h-24);g.strokeStyle='#ddd0a3';g.lineWidth=4;g.beginPath();g.moveTo(-b.w/2,-b.h/2);g.lineTo(b.w/2,-b.h/2);g.moveTo(-b.w/2,b.h/2);g.lineTo(b.w/2,b.h/2);g.stroke();g.restore();return}if(b.type==='tower'){g.fillStyle='#666b5c';g.fillRect(-b.w*.24,-b.h/2,b.w*.48,b.h);g.strokeStyle='#a7ae92';g.lineWidth=3;g.strokeRect(-b.w*.24,-b.h/2,b.w*.48,b.h);g.beginPath();g.moveTo(0,-b.h/2);g.lineTo(0,-b.h/2-35);g.stroke();g.fillStyle='#d6d3ac';g.fillRect(-b.w*.34,-b.h/2+8,b.w*.68,12);g.restore();return}
if(b.type==='factory'){g.fillStyle=['#a4a17f','#858b77','#aba58c'][b.tone];g.fillRect(-b.w/2,-b.h/2,b.w,b.h);g.fillStyle='#555f55';g.fillRect(-b.w/2+7,-b.h/2+8,b.w-14,b.h-16);g.fillStyle='#747a68';g.fillRect(-b.w/2+13,-b.h/2+13,b.w-26,b.h-26);g.strokeStyle='#c8c0a1';g.lineWidth=3;g.beginPath();g.moveTo(-b.w/2+8,0);g.lineTo(b.w/2-8,0);g.moveTo(0,-b.h/2+8);g.lineTo(0,b.h/2-8);g.stroke();g.fillStyle='#baa879';g.fillRect(-7,b.h/2-15,14,15)}else{let walls=['#cf9b64','#dbb679','#a9b88c','#d18c6f','#d4c79e'];g.fillStyle=walls[b.tone];g.fillRect(-b.w/2,-b.h/2,b.w,b.h);g.fillStyle=['#7b5541','#a55740','#63725b'][b.roof];g.fillRect(-b.w/2-4,-b.h/2-3,b.w+8,b.h+11);g.fillStyle='#dfbd86';g.fillRect(-b.w/2+5,-b.h/2+5,b.w-10,b.h-14);g.fillStyle='#594c3a';g.fillRect(-5,b.h/2-20,10,20);g.fillStyle='#8cc0ae';g.fillRect(-b.w/2+10,-b.h/2+12,12,10);g.fillRect(b.w/2-22,-b.h/2+12,12,10);g.fillStyle='#e5c986';g.fillRect(-b.w/2-4,-b.h/2-3,b.w+8,5)}
g.restore()}
function drawTree(g,t){g.save();g.translate(t.x,t.y);g.fillStyle='#0003';g.beginPath();g.ellipse(4,8,t.r*.83,t.r*.55,0,0,Math.PI*2);g.fill();g.fillStyle='#5a4833';g.fillRect(-3,-2,6,t.r*.65);let colors=['#286346','#3b8054','#2e7050','#4c8051'];g.fillStyle=colors[t.tone];g.beginPath();g.arc(-t.r*.25,-t.r*.18,t.r*.72,0,Math.PI*2);g.arc(t.r*.28,-t.r*.3,t.r*.66,0,Math.PI*2);g.arc(0,t.r*.23,t.r*.74,0,Math.PI*2);g.fill();g.fillStyle='#87a66b55';g.beginPath();g.arc(-t.r*.3,-t.r*.42,t.r*.28,0,Math.PI*2);g.fill();g.restore()}
function drawSoldier(g,e,isPlayer=false){g.save();g.translate(e.x,e.y);g.rotate(e.angle||0);g.fillStyle='#0005';g.beginPath();g.ellipse(0,6,isPlayer?13:11,7,0,0,Math.PI*2);g.fill();if(isPlayer&&e.parachute){g.strokeStyle='#e9e2c6';g.lineWidth=1.5;g.beginPath();g.moveTo(-8,-4);g.lineTo(-24,-49);g.moveTo(8,-4);g.lineTo(24,-49);g.stroke();g.fillStyle='#db5d42';g.beginPath();g.arc(0,-53,28,Math.PI,0);g.lineTo(22,-51);g.quadraticCurveTo(0,-40,-22,-51);g.fill();g.strokeStyle='#f0d7b4';g.stroke()}
g.fillStyle='#303c30';g.fillRect(-7,-8,14,17);g.fillStyle=isPlayer?'#c5d19c':'#bdc5a5';g.fillRect(-6,-9,12,13);g.fillStyle=isPlayer?'#dc704b':'#d0b886';g.beginPath();g.arc(0,-9,6.7,0,Math.PI*2);g.fill();g.fillStyle=isPlayer?'#596d48':'#65755b';g.beginPath();g.arc(0,-12,7,Math.PI,Math.PI*2);g.fill();g.fillStyle='#35402f';g.fillRect(2,-3,15,4);g.fillStyle='#262e26';g.fillRect(12,-2,12,3);if(isPlayer){g.strokeStyle='#dbf58c';g.lineWidth=1.5;g.beginPath();g.arc(0,0,13,0,Math.PI*2);g.stroke()}g.restore()}

