function drawTree(g,t){g.save();g.translate(t.x,t.y);g.fillStyle='#0003';g.beginPath();g.ellipse(4,8,t.r*.83,t.r*.55,0,0,Math.PI*2);g.fill();g.fillStyle='#5a4833';g.fillRect(-3,-2,6,t.r*.65);let colors=['#286346','#3b8054','#2e7050','#4c8051'];g.fillStyle=colors[t.tone];g.beginPath();g.arc(-t.r*.25,-t.r*.18,t.r*.72,0,Math.PI*2);g.arc(t.r*.28,-t.r*.3,t.r*.66,0,Math.PI*2);g.arc(0,t.r*.23,t.r*.74,0,Math.PI*2);g.fill();g.fillStyle='#87a66b55';g.beginPath();g.arc(-t.r*.3,-t.r*.42,t.r*.28,0,Math.PI*2);g.fill();g.restore()}
function drawLoot(g,l){if(l.taken)return;let col={ammo:'#ebc95b',med:'#78d48a',armor:'#72ccdc',grenade:'#e87954',weapon:'#e6ab68'}[l.type];g.save();g.translate(l.x,l.y);g.fillStyle='#0005';g.beginPath();g.ellipse(0,7,10,5,0,0,Math.PI*2);g.fill();g.fillStyle=col;g.fillRect(-7,-8,14,13);g.strokeStyle='#fff9';g.strokeRect(-7,-8,14,13);g.fillStyle='#fff';g.font='bold 8px sans-serif';g.textAlign='center';g.fillText({ammo:'A',med:'+',armor:'◆',grenade:'G',weapon:'↗'}[l.type],0,1);g.restore()}
function drawMap(g,size,isFull=false){g.clearRect(0,0,size,size);g.fillStyle='#28745a';g.fillRect(0,0,size,size);let s=size/W;g.save();g.scale(s,s);g.translate(0,(H-W)/2);g.fillStyle='#d5bc83';g.beginPath();g.ellipse(W/2,H/2,1250,940,0,0,Math.PI*2);g.fill();g.fillStyle='#35795d';g.beginPath();g.ellipse(W/2,H/2,1190,885,0,0,Math.PI*2);g.fill();g.strokeStyle='#9e966f';g.lineWidth=44;g.beginPath();g.moveTo(260,1050);g.bezierCurveTo(600,930,620,1130,980,1020);g.bezierCurveTo(1270,900,1440,820,1710,900);g.bezierCurveTo(1950,980,2150,1020,2340,900);g.stroke();for(const b of buildings){g.fillStyle=b.type==='factory'?'#777d6b':b.type==='bridge'?'#aaa184':'#c89768';g.fillRect(b.x-b.w/2,b.y-b.h/2,b.w,b.h)}
g.strokeStyle='#f8eed8';g.lineWidth=5;g.beginPath();g.arc(safe.x,safe.y,safe.r,0,Math.PI*2);g.stroke();g.fillStyle='#ff5944';g.beginPath();g.arc(safe.x,safe.y,safe.r,0,Math.PI*2);g.rect(W,0,-W,-H);g.fill('evenodd');if(player){g.fillStyle='#d7ff70';g.beginPath();g.arc(player.x,player.y,20,0,Math.PI*2);g.fill();g.strokeStyle='#172019';g.lineWidth=7;g.beginPath();g.moveTo(player.x,player.y);g.lineTo(player.x+Math.cos(player.angle)*45,player.y+Math.sin(player.angle)*45);g.stroke()}if(isFull){g.font='bold 28px sans-serif';g.fillStyle='#f1eddb';g.textAlign='center';for(const [name,x,y] of places)g.fillText(name,x,y)}g.restore();if(player){for(const b of bots){if(!b.alive)continue;let x=b.x/W*size,y=(b.y-(H-W)/2)/W*size;if(y>=0&&y<size){g.fillStyle='#f4775d';g.beginPath();g.arc(x,y,isFull?3:2,0,Math.PI*2);g.fill()}}let px=player.x/W*size,py=(player.y-(H-W)/2)/W*size;g.fillStyle='#e6ff99';g.beginPath();g.arc(px,py,isFull?5:3.5,0,Math.PI*2);g.fill()}}
function render(){ctx.clearRect(0,0,cw,ch);let scale=Math.min(1.13,Math.max(.7,ch/850));if(state==='lobby'||state==='result'){let t=performance.now()/1000;camera.x=clamp(1150+Math.sin(t*.12)*100-cw/2,-80,W-cw);camera.y=clamp(900+Math.cos(t*.14)*50-ch/2,-80,H-ch);scale=Math.min(1.0,Math.max(.65,ch/900));}else if(player){camera.x=player.x-cw/(2*scale);camera.y=player.y-ch/(2*scale);camera.x=clamp(camera.x,-40,W-cw/scale+40);camera.y=clamp(camera.y,-40,H-ch/scale+40)}ctx.save();ctx.scale(scale,scale);ctx.translate(-camera.x,-camera.y);drawGround(ctx);for(const t of trees)drawTree(ctx,t);for(const b of buildings)drawBuilding(ctx,b);for(const l of loot)drawLoot(ctx,l);for(const b of bots)if(b.alive)drawSoldier(ctx,b);for(const bl of bullets){ctx.fillStyle=bl.color;ctx.beginPath();ctx.arc(bl.x,bl.y,bl.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle=bl.color+'66';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(bl.x,bl.y);ctx.lineTo(bl.x-bl.vx*.025,bl.y-bl.vy*.025);ctx.stroke()}if(player&&player.alive)drawSoldier(ctx,player,true);
if(player&&state==='playing'){let sx=safe.x-camera.x,sy=safe.y-camera.y,r=safe.r;ctx.save();ctx.beginPath();ctx.rect(camera.x,camera.y,cw/scale,ch/scale);ctx.arc(safe.x,safe.y,r,0,Math.PI*2,true);ctx.fillStyle='#10231d68';ctx.fill('evenodd');ctx.restore();ctx.strokeStyle='#c9f17d';ctx.lineWidth=3/scale;ctx.setLineDash([12/scale,8/scale]);ctx.beginPath();ctx.arc(safe.x,safe.y,r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}ctx.restore();if(state==='playing'||state==='drop'){drawMap(mini,256);drawMap(full,512,true)}else{drawMap(mini,256)}if(player&&state==='playing'){let outside=dist(player,safe)>safe.r;document.querySelector('#zoneLabel').textContent=outside?'FORA DA ZONA!':'ZONA SEGURA';document.querySelector('#zoneLabel').style.color=outside?'#ff775b':''}}

