function fireShot(shooter,isPlayer,target){let w=isPlayer?weapons[player.weapon]:weapons[shooter.weapon||0];if(isPlayer){if(player.ammo<=0){showToast('SEM MUNIÇÃO · R PARA RECARREGAR');shootHeld=false;return}player.ammo--;syncHud()}let a=shooter.angle+rand(isPlayer&&aiming?-.025:-.06,isPlayer&&aiming?.025:.06);let speed=w.speed*(isPlayer?1:.72);bullets.push({x:shooter.x+Math.cos(a)*22,y:shooter.y+Math.sin(a)*22,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:1.35,damage:w.damage*(isPlayer?1:.52),owner:isPlayer?'player':shooter,target:target||null,color:isPlayer?w.color:'#f2745a',r:isPlayer?3:2.4});if(soundOn&&isPlayer&&window.AudioContext){try{let AC=window.AudioContext||window.webkitAudioContext;let ac=new AC(),o=ac.createOscillator(),gain=ac.createGain();o.type='square';o.frequency.setValueAtTime(110,ac.currentTime);o.frequency.exponentialRampToValueAtTime(45,ac.currentTime+.06);gain.gain.setValueAtTime(.035,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.075);o.connect(gain);gain.connect(ac.destination);o.start();o.stop(ac.currentTime+.08);o.onended=()=>ac.close()}catch(e){}}}
