function hurtPlayer(amount,by){if(!player||player.inv>0||!player.alive)return;let absorbed=Math.min(player.armor,amount*.7);player.armor-=absorbed;player.hp-=amount-absorbed;document.querySelector('#hitFlash').classList.remove('hit');void document.querySelector('#hitFlash').offsetWidth;document.querySelector('#hitFlash').classList.add('hit');syncHud();if(player.hp<=0){player.hp=0;syncHud();endGame(false,by)}}
